Q: How to test if expression contains specific value with NSubstitute A: <p>You could use <code>Arg.Is</code></p>
<pre class="lang-cs prettyprint-override"><code>public interface IRepo
{
    public string TestMethod(Expression&lt;Func&lt;Sender, bool&gt;&gt; expression);
}

public record Sender(string SenderId);

[Test]
public void Test()
{
    var senderId = &quot;senderId&quot;;
    var expectedValue = &quot;expectedValue&quot;;

    var fakeRepo = Substitute.For&lt;IRepo&gt;();
    fakeRepo.TestMethod(
             Arg.Is((Expression&lt;Func&lt;Sender, bool&gt;&gt; expr) =&gt; expr.Compile()(new Sender(senderId)))
        ).Returns(expectedValue);

    var result = fakeRepo.TestMethod(x =&gt; x.SenderId == senderId);
    var result2 = fakeRepo.TestMethod(x =&gt; x.SenderId == &quot;randomId&quot;);

    Assert.That(result, Is.EqualTo(expectedValue));
    Assert.That(result2, Is.Empty);
}
</code></pre>

Q: How can I debounce a search input in React so it doesn’t fire an API request on every keystroke? A: <p>You have to do <code>debouncing</code>. Here is a sample.</p>
<pre><code>import React, { useState, useEffect } from &quot;react&quot;;

export default function SearchBar() {
  const [query, setQuery] = useState(&quot;&quot;);
  const [debouncedQuery, setDebouncedQuery] = useState(&quot;&quot;);

  // Debounce logic
  useEffect(() =&gt; {
    const handler = setTimeout(() =&gt; {
      setDebouncedQuery(query);
    }, 500);

    // Cleanup runs if query changes before 500ms
    return () =&gt; {
      clearTimeout(handler);
    };
  }, [query]);

  // API call effect
  useEffect(() =&gt; {
    if (!debouncedQuery) return;

    fetch(`/api/search?q=${debouncedQuery}`)
      .then(res =&gt; res.json())
      .then(data =&gt; {
        console.log(&quot;Results:&quot;, data);
      });
  }, [debouncedQuery]);

  return (
    &lt;input
      type=&quot;text&quot;
      placeholder=&quot;Search...&quot;
      value={query}
      onChange={(e) =&gt; setQuery(e.target.value)}
    /&gt;
  );
}
</code></pre>
